<?php
declare(strict_types=1);namespace App\Http\Controllers\Finance;use App\Http\Controllers\Controller;use App\Http\Requests\Finance\SppRequest;use App\Models\{AcademicYear,Classroom,Semester};use App\Models\Finance\FeeType;use App\Services\Finance\SppGenerationService;class SppGenerationController extends Controller{private function options():array{return ['years'=>AcademicYear::latest('starts_at')->get(),'semesters'=>Semester::latest('starts_at')->get(),'classrooms'=>Classroom::with('gradeLevel')->get(),'feeTypes'=>FeeType::where('active',true)->get()];}public function create(){return view('finance.spp.generate',$this->options());}public function preview(SppRequest $r,SppGenerationService $s){return view('finance.spp.generate',$this->options()+['input'=>$r->validated(),'preview'=>$s->preview($r->validated())]);}public function generate(SppRequest $r,SppGenerationService $s){$result=$s->generate($r->validated(),$r->user()->id);return redirect()->route('finance.spp.create')->with('success',"{$result['created']} tagihan dibuat, {$result['skipped']} dilewati.");}}
